using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using AICad.Contracts;
namespace AICad.Application;
public sealed class AiProfile {public string Id{get;set;}=Guid.NewGuid().ToString("N");public string Label{get;set;}="Tài khoản AI";public bool Shared{get;set;}public DateTime ConnectedUtc{get;set;}=DateTime.UtcNow;}
public sealed class AiAccounts(InstallConfig config):IDisposable {
 readonly SemaphoreSlim gate=new(1,1);Process? login;string challenge="";AiProfile? pending;long epoch;long loginGeneration;bool disposed;
 string ProfileFile=>Path.Combine(config.DataRoot,"accounts","active.json");
 public long Epoch=>Interlocked.Read(ref epoch);
 public AiProfile? Active(){if(!File.Exists(ProfileFile))return null;return Json.Read<AiProfile>(File.ReadAllText(ProfileFile));}
 public string Home(AiProfile p)=>p.Shared?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".codex"):Path.Combine(config.DataRoot,"accounts",Json.Id(p.Id),"codex");
 public ProcessStartInfo Start(AiProfile profile,params string[] args){if(!File.Exists(config.CodexExecutable))throw new CadException("AI_NOT_INSTALLED","Codex CLI is not installed or configured.");var start=new ProcessStartInfo(config.CodexExecutable){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardInputEncoding=new System.Text.UTF8Encoding(false),StandardOutputEncoding=System.Text.Encoding.UTF8,StandardErrorEncoding=System.Text.Encoding.UTF8,WorkingDirectory=config.DataRoot};foreach(var a in args)start.ArgumentList.Add(a);start.Environment["CODEX_HOME"]=Home(profile);return start;}
 public async Task<bool> LoggedIn(AiProfile p,CancellationToken ct=default){Directory.CreateDirectory(Home(p));using var process=Process.Start(Start(p,"login","status"))!;var output=process.StandardOutput.ReadToEndAsync(ct);var error=process.StandardError.ReadToEndAsync(ct);using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(10000);try{await process.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){process.Kill(true);return false;}_=await output;_=await error;return process.ExitCode==0;}
 public object State(){var active=Active();return new{available=File.Exists(config.CodexExecutable),connected=active!=null,profile=active==null?null:new{active.Id,active.Label,active.Shared,active.ConnectedUtc},loginPending=login!=null&&!login.HasExited,challenge,scope="App-local account. Shared Codex link is disconnected locally; global Codex login is never logged out."};}
 public async Task<object> LinkExisting(CancellationToken ct){await gate.WaitAsync(ct);try{if(login!=null&&!login.HasExited)throw new CadException("LOGIN_PENDING","Hoàn tất hoặc hủy lượt đăng nhập hiện tại trước.");var p=new AiProfile{Label="Codex đã đăng nhập trên máy",Shared=true};if(!await LoggedIn(p,ct))throw new CadException("AI_LOGIN_REQUIRED","Codex on this Windows account is not signed in.");Directory.CreateDirectory(Path.GetDirectoryName(ProfileFile)!);Json.Atomic(ProfileFile,p);Interlocked.Increment(ref epoch);return State();}finally{gate.Release();}}
 public async Task<object> BeginLogin(string label,CancellationToken ct){await gate.WaitAsync(ct);try{if(login!=null&&!login.HasExited)throw new CadException("LOGIN_PENDING","Finish or cancel the current login first.");if(label.Length>80)throw new CadException("INVALID_LABEL","Account label is too long.");pending=new AiProfile{Label=string.IsNullOrWhiteSpace(label)?"Tài khoản AI của app":label};Directory.CreateDirectory(Home(pending));challenge="Đang khởi tạo đăng nhập chính thức…";login=Process.Start(Start(pending,"login","--device-auth","-c","cli_auth_credentials_store=\"file\""))!;var child=login;var p=pending;long generation=++loginGeneration;_=Task.Run(async()=>{async Task Capture(StreamReader reader){while(await reader.ReadLineAsync() is string raw){string line=System.Text.RegularExpressions.Regex.Replace(raw,@"\x1B\[[0-?]*[ -/]*[@-~]", "");if(line.Contains("http",StringComparison.OrdinalIgnoreCase)||line.Contains("code",StringComparison.OrdinalIgnoreCase)||line.Trim().Length<=24){lock(this){if(generation!=loginGeneration||disposed)continue;challenge=(challenge+"\n"+line).Trim();if(challenge.Length>2500)challenge=challenge.Substring(challenge.Length-2500);}}}}var a=Capture(child.StandardOutput);var b=Capture(child.StandardError);using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(15));try{await child.WaitForExitAsync(timeout.Token);await Task.WhenAll(a,b);await gate.WaitAsync();try{if(generation!=loginGeneration||disposed)return;if(child.ExitCode==0){Json.Atomic(ProfileFile,p);Interlocked.Increment(ref epoch);lock(this)challenge="Đăng nhập thành công.";}else lock(this)challenge="Đăng nhập chưa hoàn tất. Hãy thử lại hoặc liên kết phiên Codex đã có.";}finally{gate.Release();}}catch(OperationCanceledException){try{child.Kill(true);}catch{}lock(this)if(generation==loginGeneration&&!disposed)challenge="Đăng nhập hết thời hạn.";}});return State();}finally{gate.Release();}}
 public async Task<object> Logout(CancellationToken ct){await gate.WaitAsync(ct);try{++loginGeneration;Interlocked.Increment(ref epoch);if(login!=null&&!login.HasExited)login.Kill(true);var p=Active();if(p!=null&&!p.Shared){using var child=Process.Start(Start(p,"logout","-c","cli_auth_credentials_store=\"file\""))!;var output=child.StandardOutput.ReadToEndAsync();var error=child.StandardError.ReadToEndAsync();using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(10));try{await child.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){try{child.Kill(true);}catch{}throw new CadException("LOGOUT_INCOMPLETE","Chưa xác nhận đăng xuất tài khoản riêng. Vui lòng thử lại.");}_=await output;_=await error;if(child.ExitCode!=0)throw new CadException("LOGOUT_INCOMPLETE","Codex chưa xác nhận đăng xuất tài khoản riêng. Vui lòng thử lại.");}if(File.Exists(ProfileFile))File.Delete(ProfileFile);challenge="";pending=null;return State();}finally{gate.Release();}}
 public void Dispose(){disposed=true;Interlocked.Increment(ref loginGeneration);if(login!=null&&!login.HasExited)login.Kill(true);}
}
